mapper.update:
CREATE TABLE IF NOT EXISTS admin_user ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(50) NOT NULL, password_hash VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL ); CREATE UNIQUE INDEX IF NOT EXISTS idx_admin_user_username ON admin_user (username);
CREATE TABLE IF NOT EXISTS api_key ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, key_hash VARCHAR(64) NOT NULL, key_prefix VARCHAR(16) NOT NULL, expires_at TIMESTAMP, token_quota BIGINT, request_quota BIGINT, tokens_used BIGINT NOT NULL, requests_used BIGINT NOT NULL, is_active BOOLEAN NOT NULL, created_at TIMESTAMP NOT NULL, last_used_at TIMESTAMP, hit_count BIGINT NOT NULL, key_plain CLOB ); CREATE UNIQUE INDEX IF NOT EXISTS idx_api_key_hash ON api_key (key_hash);
CREATE TABLE IF NOT EXISTS audit_log ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(50) NOT NULL, action VARCHAR(30) NOT NULL, target VARCHAR(200), detail VARCHAR(500), ip VARCHAR(45), created_at TIMESTAMP NOT NULL ); CREATE INDEX IF NOT EXISTS idx_audit_log_time ON audit_log (created_at);
CREATE TABLE IF NOT EXISTS call_log ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, key_id BIGINT NOT NULL, key_name VARCHAR(100), request_id VARCHAR(64) NOT NULL, endpoint VARCHAR(200), model VARCHAR(100), prompt_tokens INT, completion_tokens INT, total_tokens INT, cached_tokens INT, cache_hit_rate DECIMAL(5,4), tokens_per_sec DECIMAL(8,2), started_at TIMESTAMP NOT NULL, duration_ms BIGINT, status_code INT, error_msg VARCHAR(500), request_body CLOB, response_body CLOB ); CREATE INDEX IF NOT EXISTS idx_call_log_key_id ON call_log (key_id, started_at); CREATE INDEX IF NOT EXISTS idx_call_log_time ON call_log (started_at);
CREATE TABLE IF NOT EXISTS model_config ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, config_json CLOB NOT NULL, source VARCHAR(20) NOT NULL, updated_at TIMESTAMP );
